import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { HttpClient, HttpClientModule } from '@angular/common/http';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { MatAutocompleteModule } from '@angular/material/autocomplete';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { Observable, of } from 'rxjs';
import { catchError, debounceTime, distinctUntilChanged, switchMap } from 'rxjs/operators';

interface User {
  id: number;
  name: string;
}

@Component({
  selector: 'app-user-search',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    HttpClientModule,
    MatAutocompleteModule,
    MatFormFieldModule,
    MatInputModule,
  ],
  templateUrl: './user-search.component.html',
})
export class UserSearchComponent {
  searchControl = new FormControl('');

  users$: Observable<User[]> = this.searchControl.valueChanges.pipe(
    debounceTime(300),
    distinctUntilChanged(),
    switchMap((query) => this.searchUsers(typeof query === 'string' ? query : '')),
  );

  constructor(private http: HttpClient) {}

  displayUser(user: User | string | null): string {
    return user && typeof user !== 'string' ? user.name : (user ?? '');
  }

  private searchUsers(query: string): Observable<User[]> {
    if (!query.trim()) {
      return of([]);
    }
    return this.http
      .get<User[]>('/api/users', { params: { q: query } })
      .pipe(catchError(() => of([])));
  }
}
